"""
W58-B 静态 + 手工补 1111 词词根
- A/B/C 自动: example + lemma + 后缀变形 (覆盖 ~36)
- D 通道 (词干含 root) 严格化: root 长度 >= 4 且 word 长度 > root 长度 + 1
- E 通道: 手工拆词表 (常见 prefix/root/suffix 组合)
"""
import re, json, ast
from pathlib import Path

# 1. Parse wordroot.txt
text = Path('data/external/wordroot.txt').read_text()
root_data = ast.literal_eval(text)
all_roots = set()
for root_key, info in root_data.items():
    for r in root_key.replace('-', '').split(','):
        r = r.strip().lower()
        if r and len(r) >= 3:
            all_roots.add(r)

example_to_roots = {}
for root_key, info in root_data.items():
    meaning = info.get('meaning', '')
    examples = info.get('example', [])
    for ex in examples:
        ex_low = ex.lower().strip()
        example_to_roots.setdefault(ex_low, []).append({
            'root': root_key,
            'meaning': meaning
        })

# 2. lemma.en.txt
lemma = {}
for line in Path('data/external/lemma.en.txt').read_text().splitlines():
    line = line.strip()
    if not line or line.startswith(';'):
        continue
    m = re.match(r'^(\S+)/\d+\s*->\s*(.+)$', line)
    if m:
        base = m.group(1).lower()
        variants = [v.lower().strip() for v in m.group(2).split(',')]
        lemma[base] = base
        for v in variants:
            lemma.setdefault(v, base)

