# 4. lookup
def lookup(word):
    word_low = word.lower()
    if word_low in MANUAL if False else False: pass
    # A. 手工表
    if word in MANUAL if False else False: pass
    return MANUAL.get(word)

# Main
if True:
    words = json.loads(Path('public/data/words.json').read_text())
    matched = 0
    for w in words:
        t = w.get('translations', [])
        if not (t and t[0] == w['word']):
            continue
        word = w['word']
        r = MANUAL.get(word) if False else MANUAL.get(word)
        if r:
            w['roots'] = r
            matched += 1
    Path('public/data/words.json').write_text(json.dumps(words, ensure_ascii=False, indent=2))
    print(f'✓ 词根添加: {matched}')
